def system_ui_language():
    """Resolve the launcher language from the active system locale."""
    value = next((os.environ.get(name) for name in ('LC_ALL', 'LC_MESSAGES', 'LANG', 'LANGUAGE')
                  if os.environ.get(name)), None)
    if not value:
        try:
            value = locale.getlocale()[0] or ''
        except ValueError:
            value = ''
    normalized = str(value).lower().replace('-', '_').split('.', 1)[0].split('@', 1)[0]
    if normalized.startswith(('ru', 'russian')):
        return 'ru_RU'
    if normalized.startswith(('pt', 'portuguese')):
        return 'pt_BR'
    return 'en_US'


def wrap_labels_on_resize(parent, labels):
    def update_wraplength(event):
        wraplength = max(80, event.width - 24)
        for label in labels:
            label.configure(wraplength=wraplength)

    parent.bind('<Configure>', update_wraplength, add='+')


class ScrollableFrame(ttk.Frame):
    """A frame whose vertical scrollbar is shown only when its content overflows."""

    def __init__(self, parent):
        super().__init__(parent)
        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=1)
        self.canvas = tk.Canvas(
            self, highlightthickness=0, background=ttk.Style().lookup('TFrame', 'background'))
        self.scrollbar = ttk.Scrollbar(
            self, orient='vertical', command=self.canvas.yview)
        self.canvas.configure(yscrollcommand=self.scrollbar.set)
        self.canvas.grid(row=0, column=0, sticky='nsew', padx=(0, 8))
        self.scrollbar.grid(row=0, column=1, sticky='ns')
        self.scrollbar.grid_remove()
        self.content = ttk.Frame(self.canvas)
        self.window = self.canvas.create_window((0, 0), window=self.content, anchor='nw')
        self._refresh_job = None
        self.scrollbar_visible = False
        self.content.bind('<Configure>', self._schedule_refresh, add='+')
        self.canvas.bind('<Configure>', self._resize_content, add='+')
        self._schedule_refresh()

    def _schedule_refresh(self, _event=None):
        if self._refresh_job is None and self.winfo_exists():
            self._refresh_job = self.after_idle(self._refresh)

    def refresh(self):
        self._schedule_refresh()

    def _resize_content(self, event):
        self.canvas.itemconfigure(self.window, width=event.width)
        self._schedule_refresh()

    def _refresh(self):
        self._refresh_job = None
        if not self.winfo_exists():
            return
        viewport_height = self.canvas.winfo_height()
        content_height = self.content.winfo_reqheight()
        self.canvas.itemconfigure(self.window, height=max(viewport_height, content_height))
        bounds = self.canvas.bbox(self.window)
        self.canvas.configure(scrollregion=bounds or (0, 0, 0, 0))
        self.scrollbar.set(*self.canvas.yview())
        should_scroll = content_height > viewport_height and viewport_height > 1
        if should_scroll != self.scrollbar_visible:
            if should_scroll:
                self.scrollbar.grid()
            else:
                self.scrollbar.grid_remove()
            self.scrollbar_visible = should_scroll

    def destroy(self):
        if self._refresh_job is not None:
            self.after_cancel(self._refresh_job)
            self._refresh_job = None
        super().destroy()


class PosterView(ttk.Label):
    """Display an embedded poster scaled to the available column width."""

    def __init__(self, parent, source, on_resize=None):
        super().__init__(parent, anchor='n')
        self.on_resize = on_resize
        self.source = source
        self.source_width = source.width()
        self.source_height = source.height()
        ppm = self.tk.call(source.name, 'data', '-format', 'ppm')
        _, dimensions, max_value, self.source_pixels = ppm.split(b'\n', 3)
        if dimensions != f'{self.source_width} {self.source_height}'.encode('ascii'):
            raise ValueError(f'Unexpected poster dimensions: {dimensions!r}')
        if max_value != b'255' or len(self.source_pixels) != self.source_width * self.source_height * 3:
            raise ValueError('Unsupported poster pixel format')
        self._photo = None
        self._rendered_size = None
        self._resize_job = None
        self.bind('<Configure>', self._schedule_resize, add='+')

    def _schedule_resize(self, event):
        if event.width < 2:
            return
        if self._resize_job is not None:
            self.after_cancel(self._resize_job)
        self._resize_job = self.after(50, lambda: self.fit_width(self.winfo_width()))

    def fit_width(self, width):
        if width < 2 or not self.winfo_exists():
            return
        scale = width / self.source_width
        size = (width, max(1, round(self.source_height * scale)))
        if size != self._rendered_size:
            self._photo = self._scale(*size)
            self._rendered_size = size
        self.configure(image=self._photo)
        self._resize_job = None
        if self.on_resize is not None:
            self.on_resize()

    def _scale(self, width, height):
        x_offsets = tuple(
            min(self.source_width - 1, (2 * x + 1) * self.source_width // (2 * width)) * 3
            for x in range(width))
        y_offsets = tuple(
            min(self.source_height - 1, (2 * y + 1) * self.source_height // (2 * height))
            * self.source_width * 3 for y in range(height))
        source = self.source_pixels
        row_bytes = width * 3
        scaled = bytearray(row_bytes * height)
        for y, source_row in enumerate(y_offsets):
            target_row = y * row_bytes
            scaled[target_row:target_row + row_bytes] = b''.join(
                source[source_row + x:source_row + x + 3] for x in x_offsets)
        ppm = f'P6\n{width} {height}\n255\n'.encode('ascii') + scaled
        return tk.PhotoImage(data=ppm, format='PPM', master=self)

    def destroy(self):
        if self._resize_job is not None:
            self.after_cancel(self._resize_job)
            self._resize_job = None
        super().destroy()


class Launcher:
    def __init__(self, root):
        self.root = root
        self.settings = tlg_run.load_settings()
        self.process = None
        self.lines = queue.Queue()
        self.build()
        self.root.after(100, self.pump)

    # -- language ---------------------------------------------------------------------------
    def language(self):
        choice = self.settings.get('ui_language', 'auto')
        return system_ui_language() if choice == 'auto' else choice

    def pt(self):
        return self.language() == 'pt_BR'

    def ru(self):
        return self.language() == 'ru_RU'

    def t(self, key, **fmt):
        if self.ru():
            value = TEXT_RU.get(key, TEXT[key][0])
        else:
            en, pt = TEXT[key]
            value = pt if self.pt() else en
        return value.format(**fmt)

    # -- window -----------------------------------------------------------------------------
    def build(self):
        """Rebuild the main window from its independent layout sections."""
        for child in self.root.winfo_children():
            child.destroy()
        root = self.root
        root.title(self.t('title'))
        screen_width = root.winfo_screenwidth()
        screen_height = root.winfo_screenheight()
        window_width = min(1280, screen_width - 40)
        window_height = min(800, screen_height - 80)
        root.minsize(min(1120, window_width), min(600, window_height))
        root.resizable(True, True)
        root.geometry(f'{window_width}x{window_height}+'
                      f'{max(0, (screen_width - window_width) // 2)}+'
                      f'{max(0, (screen_height - window_height - 80) // 2)}')
        pad = {'padx': 6, 'pady': 4}
        main = ttk.Frame(root, padding=12)
        main.pack(fill='both', expand=True)
        for column, weight in enumerate((3, 3, 4)):
            main.columnconfigure(column, weight=weight, uniform='cols' if column < 2 else '')
        main.rowconfigure(1, weight=1)
        self.vars = {}
        self.load_art()
        self._build_header(main)
        self._build_left_column(main, pad)
        self._build_middle_column(main, pad)
        self._build_log(main, pad)
        self._build_actions(main)
        self.refresh_status()
        root.update_idletasks()
        self.poster_view.fit_width(self.poster_view.winfo_width())

    def _build_header(self, main):
        header = ttk.Frame(main)
        header.grid(row=0, column=1, columnspan=2, sticky='ew', pady=(0, 8))
        titles = ttk.Frame(header)
        titles.pack(side='left', fill='y', padx=(4, 0))
        ttk.Label(titles, text='The Last Guardian', font=('TkDefaultFont', 22, 'bold')).pack(anchor='w')
        ttk.Label(titles, text='PC — CUSA03627 v1.03', foreground='#777').pack(anchor='w')
        credits = ttk.Frame(header)
        credits.pack(side='right', anchor='ne')
        for name, url in CONTRIBUTORS:
            link = ttk.Label(credits, text=name, foreground='#2a6fdb', cursor='hand2',
                             font=('TkDefaultFont', 10, 'underline'))
            link.pack(anchor='e')
            link.bind('<Button-1>', lambda _, u=url: webbrowser.open(u))
        status_area = ttk.Frame(titles)
        status_area.pack(anchor='w', fill='x', pady=(10, 0))
        status_area.columnconfigure(0, weight=1)
        status_area.rowconfigure(0, minsize=2 * tkfont.nametofont('TkDefaultFont').metrics('linespace') + 4)
        self.status = ttk.Label(status_area, text='', foreground='#555', wraplength=420, justify='left')
        self.status.grid(sticky='w')

    def _build_left_column(self, main, pad):
        left_area = ScrollableFrame(main)
        left_area.grid(row=0, column=0, rowspan=2, sticky='nsew', **pad)
        left = left_area.content
        left.columnconfigure(0, weight=1)
        poster_area = ttk.Frame(left)
        poster_area.pack(fill='x')
        poster_view = PosterView(poster_area, self.poster_source, on_resize=left_area.refresh)
        poster_view.pack(fill='x')
        self.poster_view = poster_view

        left_settings = ttk.Frame(left)
        left_settings.pack(side='bottom', fill='x')
        left_settings.columnconfigure(0, weight=1)
        game = ttk.LabelFrame(left_settings, text=self.t('game'), padding=8)
        game.grid(sticky='ew', pady=(0, 8))
        game.columnconfigure(0, weight=1)
        for row, key in enumerate(('game_dir',)):
            ttk.Label(game, text=self.t(key)).grid(row=row * 2, column=0, columnspan=2, sticky='w')
            var = tk.StringVar(value=self.settings[key])
            var.trace_add('write', lambda *_: self.changed())
            self.vars[key] = var
            ttk.Entry(game, textvariable=var).grid(row=row * 2 + 1, column=0, sticky='ew', pady=(0, 6))
            ttk.Button(game, text=self.t('browse'), command=lambda k=key: self.browse(k)).grid(
                row=row * 2 + 1, column=1, padx=(6, 0), pady=(0, 6))
        controls = ttk.LabelFrame(left_settings, text=self.t('controls'), padding=8)
        controls.grid(sticky='ew')
        controls.columnconfigure(0, weight=1)
        self.check(controls, 0, 'mouse_enabled')
        self.check(controls, 1, 'mouse_invert_y')
        sensitivity_label = ttk.Label(controls, text=self.t('mouse_sensitivity'), wraplength=320)
        sensitivity_label.grid(row=2, column=0, columnspan=3, sticky='w', pady=(4, 0))
        sens = tk.DoubleVar(value=float(self.settings.get('mouse_sensitivity', 1.0)))
        self.vars['mouse_sensitivity'] = sens
        sens_spin = ttk.Spinbox(controls, from_=0.1, to=5.0, increment=0.1, format='%.2f', textvariable=sens,
                                width=6, command=self.changed)
        sens_spin.grid(row=3, column=0, sticky='w', padx=6, pady=(2, 0))
        sens_spin.bind('<FocusOut>', lambda _: self.changed())
        mouse_hint = ttk.Label(controls, text=self.t('mouse_hint'), foreground='#777',
                               wraplength=320, justify='left')
        mouse_hint.grid(row=4, column=0, columnspan=3, sticky='w', pady=(2, 0))

        wrap_labels_on_resize(controls, (sensitivity_label, mouse_hint))

    def _build_middle_column(self, main, pad):
        middle_area = ScrollableFrame(main)
        middle_area.grid(row=1, column=1, sticky='nsew', **pad)
        middle = middle_area.content
        middle.columnconfigure(0, weight=1)
        lang = ttk.LabelFrame(middle, text=self.t('language'), padding=8)
        lang.grid(sticky='ew', pady=(0, 8))
        lang.columnconfigure(0, weight=1)
        self.game_lang_box = None
        self.build_game_language(lang)
        self.combo(lang, 2, 'ui_language', UI_LANGUAGES,
                   lambda k: self.t('auto') if k == 'auto' else UI_LANGUAGE_NAMES[k], on_change=self.build)
        video = ttk.LabelFrame(middle, text=self.t('video'), padding=8)
        video.grid(sticky='ew')
        video.columnconfigure(0, weight=1)
        self.combo(video, 0, 'display_mode', DISPLAY_MODES, lambda k: self.t(k))
        self.check(video, 2, 'vsync')
        self.check(video, 3, 'show_fps')
        ttk.Label(video, text=self.t('vram'), wraplength=320).grid(
            row=4, column=0, sticky='w', pady=(6, 0))
        vram = tk.IntVar(value=int(self.settings['vram_budget_mb']))
        self.vars['vram_budget_mb'] = vram
        spin = ttk.Spinbox(video, from_=2000, to=24000, increment=200, textvariable=vram, width=8,
                           command=self.changed)
        spin.grid(row=5, column=0, sticky='w', padx=6, pady=(2, 0))
        spin.bind('<FocusOut>', lambda _: self.changed())
        vram_hint = ttk.Label(video, text=self.t('vram_hint'), foreground='#777',
                              wraplength=320, justify='left')
        vram_hint.grid(row=6, column=0, sticky='w')
        self.combo(video, 7, 'frame_rate', tlg_run.FRAME_RATES, lambda k: self.t(f'fps_{k}'))
        fps_hint = ttk.Label(video, text=self.t('fps_hint'), foreground='#777',
                             wraplength=320, justify='left')
        fps_hint.grid(row=9, column=0, sticky='w')
        self.combo(video, 10, 'resolution', tlg_run.RESOLUTIONS, lambda k: self.t(f'res_{k}'))
        resolution_hint = ttk.Label(video, text=self.t('resolution_hint'), foreground='#777',
                                    wraplength=320, justify='left')
        resolution_hint.grid(row=13, column=0, sticky='w', pady=(2, 0))
        video_labels = (vram_hint, fps_hint, resolution_hint)

        wrap_labels_on_resize(video, video_labels)
        self.build_filters(video, 14)

    def _build_log(self, main, pad):
        log_frame = ttk.LabelFrame(main, text=self.t('log'), padding=4)
        log_frame.grid(row=1, column=2, sticky='nsew', **pad)
        self.log = tk.Text(log_frame, wrap='none', font=('TkFixedFont', 9), state='disabled', width=60)
        scroll = ttk.Scrollbar(log_frame, command=self.log.yview)
        self.log.configure(yscrollcommand=scroll.set)
        self.log.pack(side='left', fill='both', expand=True)
        scroll.pack(side='right', fill='y')

    def _build_actions(self, main):
        buttons = ttk.Frame(main)
        buttons.grid(row=2, column=0, columnspan=3, sticky='ew', pady=(10, 0))
        ttk.Button(buttons, text=self.t('quit'), command=self.quit).pack(side='left')
        ttk.Button(buttons, text=self.t('remap'), command=self.remap_dialog).pack(side='left', padx=6)
        style = ttk.Style()
        style.configure('Play.TButton', font=('TkDefaultFont', 13, 'bold'))
        self.play_button = ttk.Button(buttons, text=self.t('play'), style='Play.TButton', command=self.play)
        self.play_button.pack(side='right', ipadx=30, ipady=8)
        ttk.Button(buttons, text=self.t('logs'), command=lambda: self.open(tlg_run.LOG_DIR)).pack(side='right', padx=6)
        ttk.Button(buttons, text=self.t('advanced'), command=self.advanced_dialog).pack(side='right', padx=6)
        ttk.Button(buttons, text=self.t('saves'), command=lambda: self.open(tlg_run.USER_DIR / 'savedata')).pack(side='right')
        self.cache_button = ttk.Button(buttons, text=self.t('clear_cache'), command=self.clear_cache)
        self.cache_button.pack(side='right', padx=(0, 6))

    def load_art(self):
        """Load the port icon and included vertical poster."""
        if getattr(self, 'art_loaded', False):
            return
        self.art_loaded = True
        icon = tlg_run.PORT_DIR / 'launcher' / 'tlg.png'  # the port's own icon
        if icon.is_file():
            self.icon = tk.PhotoImage(file=str(icon))
            self.root.iconphoto(True, self.icon)
        self.poster_source = tk.PhotoImage(data=POSTER_DATA, format='png', master=self.root)

    def build_filters(self, parent, row):
        """SMAA, sharpening and color adjustments, read from and written to tlg.ini right away."""
        ttk.Separator(parent).grid(row=row, column=0, columnspan=2, sticky='ew', pady=(8, 4))
        filters_label = ttk.Label(parent, text=self.t('filters'), foreground='#555',
                                  wraplength=320, justify='left')
        filters_label.grid(row=row + 1, column=0, columnspan=2, sticky='w')
        filter_labels = [filters_label]

        wrap_labels_on_resize(parent, filter_labels)
        ini = dict(INI_DEFAULTS)
        ini.update({k: v for k, v in tlg_run.read_ini(tlg_run.USER_DIR / 'tlg.ini').items() if k in ini})
        self.ini_vars = {}
        for offset, key in ((2, 'smaa'), (4, 'color_adjust')):
            var = tk.BooleanVar(value=ini[key] not in ('0', ''))
            self.ini_vars[key] = var
            ttk.Checkbutton(parent, text=self.t(key), variable=var, command=self.filters_changed).grid(
                row=row + offset, column=0, columnspan=2, sticky='w', pady=2)
        sharpening_label = ttk.Label(parent, text=self.t('sharpening'), wraplength=320)
        sharpening_label.grid(
            row=row + 5, column=0, columnspan=2, sticky='w')
        filter_labels.append(sharpening_label)
        self.sharpener = ttk.Combobox(parent, values=[self.t('sharpen_' + k) for k in SHARPENERS],
                                      state='readonly', width=16)
        self.sharpener.current(2 if ini['cas'] not in ('0', '') else 1 if ini['rcas'] not in ('0', '') else 0)
        self.sharpener.grid(row=row + 6, column=0, sticky='w', padx=6, pady=2)
        self.sharpener.bind('<<ComboboxSelected>>', lambda _: self.filters_changed())
        for index, key in enumerate(COLOR_RANGES):
            low, high = COLOR_RANGES[key]
            label_row = row + 7 + index * 2
            color_label = ttk.Label(parent, text=self.t(key), wraplength=320)
            color_label.grid(
                row=label_row, column=0, columnspan=2, sticky='w', padx=(16, 0))
            filter_labels.append(color_label)
            var = tk.StringVar(value=ini[key])
            self.ini_vars[key] = var
            spin = ttk.Spinbox(parent, from_=low, to=high, increment=0.05, format='%.2f', textvariable=var,
                               width=6, command=self.filters_changed)
            spin.grid(row=label_row + 1, column=0, sticky='w', padx=6, pady=1)
            spin.bind('<FocusOut>', lambda _: self.filters_changed())

    def filters_changed(self):
        values = {'smaa': int(self.ini_vars['smaa'].get()), 'color_adjust': int(self.ini_vars['color_adjust'].get()),
                  'rcas': int(self.sharpener.current() == 1), 'cas': int(self.sharpener.current() == 2)}
        for key, (low, high) in COLOR_RANGES.items():
            try:
                value = min(max(float(self.ini_vars[key].get().replace(',', '.')), low), high)
            except ValueError:
                continue  # while typing
            values[key] = f'{value:.2f}'
        tlg_run.USER_DIR.mkdir(parents=True, exist_ok=True)
        tlg_run.update_ini(tlg_run.USER_DIR / 'tlg.ini', values)

    def save_settings(self):
        self.settings = tlg_run.normalize_settings(self.settings)
        tlg_run.save_settings(self.settings)

    def combo(self, parent, row, key, values, label, on_change=None):
        label_widget = ttk.Label(parent, text=self.t(key), wraplength=320)
        label_widget.grid(row=row, column=0, columnspan=2, sticky='w')
        wrap_labels_on_resize(parent, (label_widget,))
        names = [label(v) for v in values]
        box = ttk.Combobox(parent, values=names, state='readonly', width=28)
        current = self.settings.get(key, values[0])
        box.current(values.index(current) if current in values else 0)
        box.grid(row=row + 1, column=0, columnspan=2, sticky='ew', padx=6, pady=2)

        def picked(_):
            self.settings[key] = values[box.current()]
            self.save_settings()
            if on_change:
                on_change()
            else:
                self.refresh_status()
        box.bind('<<ComboboxSelected>>', picked)
        return box

    # -- game language (depends on the loaded CUSA) ---------------------------------------------
    def build_game_language(self, parent):
        """Game language: the ones the loaded CUSA ships (by its title id), US by default."""
        label = ttk.Label(parent, text=self.t('game_language'), wraplength=320)
        label.grid(row=0, column=0, sticky='w')
        wrap_labels_on_resize(parent, (label,))
        self.game_lang_box = ttk.Combobox(parent, state='readonly', width=28)
        self.game_lang_box.grid(row=1, column=0, sticky='ew', padx=6, pady=2)
        self.game_lang_box.bind('<<ComboboxSelected>>', self.picked_language)
        self.refresh_language_choices()

    def picked_language(self, _=None):
        values = self.game_lang_values
        self.settings['game_language'] = values[self.game_lang_box.current()]
        self.save_settings()
        self.refresh_status()

    def refresh_language_choices(self):
        """Reload the combo for the game folder: another CUSA ships another set of languages."""
        if getattr(self, 'game_lang_box', None) is None:
            return
        values = list(tlg_run.game_languages(self.settings.get('game_dir')))
        self.game_lang_values = values
        self.game_lang_box.configure(values=[GAME_LANGUAGE_NAMES.get(v, v) for v in values])
        current = self.settings.get('game_language')
        if current not in values:
            current = tlg_run.default_language(self.settings.get('game_dir'))
        if current not in values:
            current = values[0]
        self.game_lang_box.current(values.index(current))
        if current != self.settings.get('game_language'):
            self.settings['game_language'] = current
            self.save_settings()

    def remap_dialog(self):
        """Remap keyboard stick directions and PS4 buttons."""
        if getattr(self, 'remap_window', None) and self.remap_window.winfo_exists():
            self.remap_window.lift()
            return
        win = self.remap_window = tk.Toplevel(self.root)
        win.title(self.t('remap_title'))
        win.resizable(False, False)
        win.transient(self.root)
        frame = ttk.Frame(win, padding=8)
        frame.pack(fill='both', expand=True)
        table = ttk.LabelFrame(frame, text=self.t('binding_group'), padding=8)
        table.grid(row=0, column=0, sticky='nsew')
        frame.columnconfigure(0, weight=1)
        mapping = dict(self.settings.get('key_map') or {})
        entries = {}
        fixed_mouse = {
            'circle': self.t('mouse_left'), 'r1': self.t('mouse_right'),
            'left': self.t('wheel_down'), 'right': self.t('wheel_up'),
        }
        configured_stick_keys = self.settings.get('stick_keys')
        stick_mapping = dict(tlg_run.DEFAULT_STICK_KEYS)
        if isinstance(configured_stick_keys, dict):
            stick_mapping.update({key: value for key, value in configured_stick_keys.items()
                                  if key in stick_mapping and isinstance(value, str) and value.strip()})
        stick_entries = {}
        disabled_stick_keys = {
            action for action, key in stick_mapping.items() if key.casefold() == 'none'
        }
        disabled_button_keys = set()
        half = (len(PS4_BUTTONS) + 1) // 2
        for column, heading_key in ((0, 'action'), (1, 'key'), (3, 'mouse'),
                                    (4, 'action'), (5, 'key'), (7, 'mouse')):
            ttk.Label(table, text=self.t(heading_key), font=('TkDefaultFont', 9, 'bold')).grid(
                row=0, column=column, sticky='w', padx=(0, 5), pady=(0, 2))
        table.columnconfigure(1, weight=1)
        table.columnconfigure(5, weight=1)
        table.columnconfigure(3, minsize=88)
        table.columnconfigure(7, minsize=88)

        def commit():
            overrides = {}
            for button, entry in entries.items():
                keyboard = entry.get().strip()
                default_keyboard, _ = split_key_bindings(tlg_run.DEFAULT_KEYS[button])
                if button in disabled_button_keys:
                    keyboard = 'none'
                elif not keyboard:
                    keyboard = default_keyboard
                    entry.delete(0, 'end')
                    entry.insert(0, keyboard)
                value = keyboard
                if value != tlg_run.DEFAULT_KEYS[button]:
                    overrides[button] = value
            self.settings['key_map'] = overrides
            stick_keys = {}
            for action, entry in stick_entries.items():
                key = entry.get().strip()
                if action in disabled_stick_keys:
                    key = 'none'
                elif not key:
                    key = tlg_run.DEFAULT_STICK_KEYS[action]
                    entry.delete(0, 'end')
                    entry.insert(0, key)
                stick_keys[action] = key
            self.settings['stick_keys'] = stick_keys
            self.save_settings()

        def manually_edited(identifier, stick):
            if stick:
                disabled_stick_keys.discard(identifier)
            else:
                disabled_button_keys.discard(identifier)

        def assign_key(target, name, stick):
            key = name.casefold()
            for action, entry in stick_entries.items():
                if stick and action == target:
                    continue
                if entry.get().strip().casefold() == key:
                    entry.delete(0, 'end')
                    disabled_stick_keys.add(action)
            for button, entry in entries.items():
                if not stick and button == target:
                    continue
                keyboard = split_key_bindings(entry.get())[0]
                bindings = [part for part in keyboard.split('|') if part and part.casefold() != 'none']
                remaining = [part for part in bindings if part.casefold() != key]
                if len(remaining) != len(bindings):
                    entry.delete(0, 'end')
                    entry.insert(0, '|'.join(remaining))
                    if not remaining:
                        disabled_button_keys.add(button)

        def capture(button, entry, set_button, stick=False):
            set_button.configure(text=self.t('press'))
            win.focus_set()

            def done(name):
                for sequence in ('<KeyPress>', '<ButtonPress>'):
                    win.unbind(sequence)
                set_button.configure(text=self.t('set'))
                if name:
                    if stick:
                        disabled_stick_keys.discard(button)
                    else:
                        disabled_button_keys.discard(button)
                    assign_key(button, name, stick)
                    entry.delete(0, 'end')
                    entry.insert(0, name)

            def key(event):
                if event.keysym == 'Escape':
                    done(None)
                else:
                    done(sdl_key_name(event.keysym))
                return 'break'

            def mouse(event):
                return 'break'
            win.after(150, lambda: (win.bind('<KeyPress>', key), win.bind('<ButtonPress>', mouse)))

        walk_actions = (
            ('walk_up', 'walk_forward'), ('walk_left', 'walk_left'),
            ('walk_down', 'walk_backward'), ('walk_right', 'walk_right'),
        )
        camera_actions = (
            ('camera_up', 'camera_up'), ('camera_left', 'camera_left'),
            ('camera_down', 'camera_down'), ('camera_right', 'camera_right'),
        )
        left_items = [('stick', action, label) for action, label in walk_actions]
        right_items = [('stick', action, label) for action, label in camera_actions]
        def localized(values):
            return values[2] if self.ru() else values[1] if self.pt() else values[0]

        left_items.extend(('button', button, f'{localized(name)} — {localized(action)}')
                          for button, name, action in PS4_BUTTONS[:half])
        right_items.extend(('button', button, f'{localized(name)} — {localized(action)}')
                           for button, name, action in PS4_BUTTONS[half:])

        for index, (left_item, right_item) in enumerate(zip(left_items, right_items), start=1):
            for item, column in ((left_item, 0), (right_item, 4)):
                kind, identifier, label = item
                row = index
                if kind == 'stick':
                    label = self.t(label)
                ttk.Label(table, text=label).grid(row=row, column=column, sticky='w', padx=(0, 5), pady=0)
                entry = ttk.Entry(table, width=12 if kind == 'stick' else 14)
                if kind == 'stick':
                    if identifier in disabled_stick_keys:
                        entry.insert(0, '')
                    else:
                        entry.insert(0, stick_mapping[identifier])
                    stick_entries[identifier] = entry
                else:
                    override = mapping.get(identifier)
                    current = override or tlg_run.DEFAULT_KEYS[identifier]
                    keyboard, _ = split_key_bindings(current)
                    if keyboard.casefold() == 'none':
                        disabled_button_keys.add(identifier)
                        keyboard = ''
                    entry.insert(0, keyboard)
                    entries[identifier] = entry
                    ttk.Label(table, text=fixed_mouse.get(identifier, ''), foreground='#888', width=12).grid(
                        row=row, column=column + 3, sticky='w', padx=(2, 4))
                entry.grid(row=row, column=column + 1, sticky='ew', pady=0)
                entry.bind('<KeyRelease>', lambda _, key=identifier, is_stick=kind == 'stick':
                           manually_edited(key, is_stick))
                set_button = ttk.Button(table, text=self.t('set'), width=7)
                set_button.configure(command=lambda b=identifier, e=entry, s=set_button, is_stick=kind == 'stick':
                                     capture(b, e, s, stick=is_stick))
                set_button.grid(row=row, column=column + 2, padx=3, pady=0)

        bottom = ttk.Frame(frame)
        bottom.grid(row=1, column=0, sticky='ew', pady=(8, 0))
        bottom.columnconfigure(0, weight=1, uniform='dialog-buttons')
        bottom.columnconfigure(1, weight=1, uniform='dialog-buttons')

        def reset():
            disabled_stick_keys.clear()
            disabled_button_keys.clear()
            for action, entry in stick_entries.items():
                entry.delete(0, 'end')
                entry.insert(0, tlg_run.DEFAULT_STICK_KEYS[action])
            for button, entry in entries.items():
                keyboard, _ = split_key_bindings(tlg_run.DEFAULT_KEYS[button])
                entry.delete(0, 'end')
                entry.insert(0, keyboard)
            commit()
        def save_and_close():
            commit()
            win.destroy()
        ttk.Button(bottom, text=self.t('reset'), command=reset).grid(
            row=0, column=0, sticky='ew', padx=(0, 4))
        ttk.Button(bottom, text=self.t('save'), command=save_and_close).grid(
            row=0, column=1, sticky='ew', padx=(4, 0))
        win.update_idletasks()
        width = min(frame.winfo_reqwidth() + 16, win.winfo_screenwidth() - 20)
        height = min(frame.winfo_reqheight() + 16, win.winfo_screenheight() - 60)
        x = max(0, min(win.winfo_screenwidth() - width,
                       self.root.winfo_rootx() + (self.root.winfo_width() - width) // 2))
        y = max(0, min(win.winfo_screenheight() - height,
                       self.root.winfo_rooty() + (self.root.winfo_height() - height) // 2))
        win.geometry(f'{width}x{height}+{x}+{y}')

    def check(self, parent, row, key):
        var = tk.BooleanVar(value=bool(self.settings[key]))
        self.vars[key] = var
        ttk.Checkbutton(parent, text=self.t(key), variable=var, command=self.changed).grid(
            row=row, column=0, columnspan=3, sticky='w', pady=2)

    # -- actions ----------------------------------------------------------------------------
    def changed(self):
        for key, var in self.vars.items():
            try:
                self.settings[key] = var.get()
            except tk.TclError:
                pass  # spinbox while typing
        self.save_settings()
        self.refresh_language_choices()
        self.refresh_status()

    def refresh_status(self):
        problems = tlg_run.check_game(self.settings['game_dir'])
        if problems:
            text = '; '.join(self.t('not_built') if k == 'not_built' else f"{self.t('missing')}: {d}"
                             for k, d in problems)
        else:
            text = self.t('ready')
        self.status.configure(text=f'{text}  {self.t("audio_status")}')
        self.play_button.configure(state='disabled' if problems or self.process else 'normal')
        self.cache_button.configure(state='disabled' if self.process else 'normal')

    def browse(self, key):
        path = filedialog.askdirectory(initialdir=self.vars[key].get() or str(Path.home()))
        if path:
            self.vars[key].set(path)

    def open(self, path):
        Path(path).mkdir(parents=True, exist_ok=True)
        if os.name == 'nt':
            os.startfile(path)  # noqa: S606 (local folder)
        else:
            subprocess.Popen(['xdg-open', str(path)])

    def clear_cache(self):
        """Clear shader cache: asks first, never while the game runs; shows how much was freed."""
        if self.process:
            messagebox.showinfo(self.t('title'), self.t('already'))
            return
        size = tlg_run.shader_cache_size(self.settings)
        if not size:
            messagebox.showinfo(self.t('clear_cache'), self.t('clear_cache_empty'))
            return
        if not messagebox.askyesno(self.t('clear_cache'),
                                   self.t('clear_cache_ask', size=tlg_run.shader_cache.human_size(size))):
            return
        try:
            freed, failures = tlg_run.clear_shader_cache(self.settings)
        except Exception as error:  # shown to the user, the launcher keeps running
            messagebox.showerror(self.t('error'), str(error))
            return
        freed = tlg_run.shader_cache.human_size(freed)
        if failures:
            message = self.t('clear_cache_failed', size=freed, count=len(failures))
            messagebox.showwarning(self.t('clear_cache'), message)
        else:
            message = self.t('clear_cache_done', size=freed)
            messagebox.showinfo(self.t('clear_cache'), message)
        self.append(message)

    def advanced_dialog(self):
        """The supported GPU readback controls. Each option shows its default and the reason."""
        if getattr(self, 'advanced_window', None) and self.advanced_window.winfo_exists():
            self.advanced_window.lift()
            return
        win = self.advanced_window = tk.Toplevel(self.root)
        win.title(self.t('advanced_title'))
        win.resizable(False, True)
        win.transient(self.root)
        window_height = min(760, max(320, win.winfo_screenheight() - 80))
        win.geometry(f'800x{window_height}')
        win.minsize(780, min(440, window_height))

        container = ttk.Frame(win, padding=12)
        container.pack(fill='both', expand=True)
        container.columnconfigure(0, weight=1)
        container.rowconfigure(0, weight=1)
        canvas = tk.Canvas(container, highlightthickness=0)
        scrollbar = ttk.Scrollbar(container, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.grid(row=0, column=0, sticky='nsew', padx=(0, 10))
        scrollbar.grid(row=0, column=1, sticky='ns')
        frame = ttk.Frame(canvas)
        content_window = canvas.create_window((0, 0), window=frame, anchor='nw')
        frame.bind('<Configure>', lambda _event: canvas.configure(scrollregion=canvas.bbox('all')))
        canvas.bind('<Configure>', lambda event: canvas.itemconfigure(content_window, width=event.width))

        def scroll(event):
            if event.num == 4:
                canvas.yview_scroll(-1, 'units')
            elif event.num == 5:
                canvas.yview_scroll(1, 'units')
            elif event.delta:
                units = -int(event.delta / 120) if abs(event.delta) >= 120 else (-1 if event.delta > 0 else 1)
                canvas.yview_scroll(units, 'units')
            return 'break'

        win.bind('<MouseWheel>', scroll)
        win.bind('<Button-4>', scroll)
        win.bind('<Button-5>', scroll)
        frame.columnconfigure(0, weight=1)
        ttk.Label(frame, text=self.t('advanced_hint'), wraplength=740, justify='left').grid(
            row=0, column=0, sticky='ew', pady=(0, 8))

        mode_frame = ttk.LabelFrame(frame, text=self.t('gpu_readbacks'), padding=8)
        mode_frame.grid(row=1, column=0, sticky='ew', pady=(0, 8))
        modes = ('2', '1', '0')
        mode = ttk.Combobox(mode_frame, state='readonly', width=20,
                            values=[self.t('readbacks_' + value) for value in modes])
        current = str(self.settings.get('gpu_readbacks', '2'))
        mode.current(modes.index(current) if current in modes else 0)
        mode.grid(row=0, column=0, sticky='w')

        def save_mode(_=None):
            value = modes[mode.current()]
            if value == '2':
                self.settings.pop('gpu_readbacks', None)
            else:
                self.settings['gpu_readbacks'] = value
            self.save_settings()

        mode.bind('<<ComboboxSelected>>', save_mode)
        mode_note = (self.t('gpu_readbacks_hint') + '\n' +
                     self.t('mark_default', value=self.t('readbacks_2')) + ' — ' +
                     self.t('gpu_readbacks_why'))
        ttk.Label(mode_frame, text=mode_note, foreground='#777', wraplength=720,
                  justify='left').grid(row=1, column=0, sticky='w', pady=(6, 0))

        draw_frame = ttk.LabelFrame(frame, text=self.t('draw_pipe'), padding=8)
        draw_frame.grid(row=2, column=0, sticky='ew', pady=(0, 8))
        draw_modes = ('auto', 'on', 'off')
        draw_pipe = ttk.Combobox(draw_frame, state='readonly', width=24,
                                 values=[self.t('draw_pipe_' + value) for value in draw_modes])
        current_draw_pipe = str(self.settings.get('draw_pipe', 'auto')).lower()
        draw_pipe.current(draw_modes.index(current_draw_pipe) if current_draw_pipe in draw_modes else 0)
        draw_pipe.grid(row=0, column=0, sticky='w')

        def save_draw_pipe(_=None):
            value = draw_modes[draw_pipe.current()]
            if value == 'auto':
                self.settings.pop('draw_pipe', None)
            else:
                self.settings['draw_pipe'] = value
            self.save_settings()

        draw_pipe.bind('<<ComboboxSelected>>', save_draw_pipe)
        ttk.Label(draw_frame, text=self.t('draw_pipe_hint'), foreground='#777', wraplength=720,
                  justify='left').grid(row=1, column=0, sticky='w', pady=(6, 0))

        columns = ttk.Frame(frame)
        columns.grid(row=3, column=0, sticky='nsew')
        columns.columnconfigure(0, weight=1)
        columns.columnconfigure(1, weight=1)
        rows = [0, 0]

        def place(column):
            row = rows[column]
            rows[column] += 2
            return columns, row, column

        def note(parent, row, column, key, default):
            state = self.t('mark_on' if default else 'mark_off')
            detail = (self.t(key + '_hint') + '\n' +
                      self.t('mark_default', value=state) + ' — ' + self.t(key + '_why'))
            ttk.Label(parent, text=detail, foreground='#777', wraplength=350,
                      justify='left').grid(row=row + 1, column=column, sticky='w',
                                           padx=4, pady=(0, 8))

        variables = {}
        flags = tlg_run.READBACK_FLAGS
        for index, (key, _env_key, default) in enumerate(flags):
            column = 0 if default else 1
            parent, row, column = place(column)
            cell = ttk.Frame(parent, padding=(4, 2))
            cell.grid(row=row, column=column, sticky='new', padx=4, pady=2)
            var = tk.BooleanVar(value=bool(self.settings.get(key, default)))
            variables[key] = var

            def toggled(k=key, v=var, d=default):
                if v.get() == d:
                    self.settings.pop(k, None)
                else:
                    self.settings[k] = v.get()
                self.save_settings()

            ttk.Checkbutton(cell, text=self.t(key), variable=var, command=toggled).grid(
                row=0, column=0, sticky='w')
            note(cell, 0, 0, key, default)

        keep_parent, keep_row, keep_column = place(1)
        keep_cell = ttk.Frame(keep_parent, padding=(4, 2))
        keep_cell.grid(row=keep_row, column=keep_column, sticky='new', padx=4, pady=2)
        keep_gpu_var = tk.BooleanVar(value=bool(self.settings.get('keep_gpu_textures', True)))
        variables['keep_gpu_textures'] = keep_gpu_var

        def keep_gpu_toggled():
            self.settings['keep_gpu_textures'] = keep_gpu_var.get()
            self.save_settings()

        ttk.Checkbutton(keep_cell, text=self.t('keep_gpu_textures'), variable=keep_gpu_var,
                        command=keep_gpu_toggled).grid(row=0, column=0, sticky='w')
        note(keep_cell, 0, 0, 'keep_gpu_textures', True)

        batch_frame = ttk.LabelFrame(frame, text=self.t('readback_batch'), padding=8)
        batch_frame.grid(row=4, column=0, sticky='ew', pady=(8, 0))
        sizes = ('0', '16', '64')
        batch = ttk.Combobox(batch_frame, state='readonly', width=26,
                             values=[self.t('readback_batch_' + value) for value in sizes])
        ini_path = tlg_run.USER_DIR / 'tlg.ini'
        current_batch = tlg_run.read_ini(ini_path).get('readback_batch', '0')
        batch.current(sizes.index(current_batch) if current_batch in sizes else 0)
        batch.grid(row=0, column=0, sticky='w')
        batch_note = (self.t('readback_batch_hint') + '\n' +
                      self.t('mark_default', value=self.t('readback_batch_0')) + ' — ' +
                      self.t('readback_batch_why'))
        ttk.Label(batch_frame, text=batch_note, foreground='#777', wraplength=720,
                  justify='left').grid(row=1, column=0, sticky='w', pady=(6, 0))

        def save_batch(_=None):
            tlg_run.USER_DIR.mkdir(parents=True, exist_ok=True)
            tlg_run.update_ini(ini_path, {'readback_batch': sizes[batch.current()]})

        batch.bind('<<ComboboxSelected>>', save_batch)

        bottom = ttk.Frame(container)
        bottom.grid(row=1, column=0, columnspan=2, sticky='ew', pady=(12, 0))

        def reset():
            self.settings = tlg_run.reset_advanced_settings(self.settings)
            for key, _env_key, default in flags:
                variables[key].set(default)
            keep_gpu_var.set(True)
            mode.current(0)
            draw_pipe.current(0)
            batch.current(0)

        ttk.Button(bottom, text=self.t('reset'), command=reset).pack(side='left')
        ttk.Button(bottom, text=self.t('close'), command=win.destroy).pack(side='right')

    def append(self, line):
        self.log.configure(state='normal')
        self.log.insert('end', line if line.endswith('\n') else line + '\n')
        if int(self.log.index('end-1c').split('.')[0]) > 2000:
            self.log.delete('1.0', '500.0')
        self.log.see('end')
        self.log.configure(state='disabled')

    def play(self):
        if self.process:
            messagebox.showinfo(self.t('title'), self.t('already'))
            return
        self.changed()
        self.append(self.t('preparing'))
        self.play_button.configure(state='disabled')
        self.cache_button.configure(state='disabled')
        threading.Thread(target=self.run_game, daemon=True).start()

    def run_game(self):
        try:
            tlg_run.prepare(self.settings, log=lambda line: self.lines.put(line))
            self.process, log = tlg_run.launch(self.settings)
        except Exception as error:  # shown to the user, the launcher keeps running
            self.lines.put(('error', str(error)))
            return
        self.lines.put(f"{self.t('running')} {log}")
        with open(log, 'w', encoding='utf-8') as out:
            out.write(f'Frame rate: requested {tlg_run.frame_rate(self.settings)}, applied {tlg_run.applied_frame_rate}\n')
            for line in self.process.stdout:
                out.write(line)
                out.flush()
                self.lines.put(line.rstrip('\n'))
        code = self.process.wait()
        self.process = None
        self.lines.put(('ended', code))

    def pump(self):
        try:
            while True:
                item = self.lines.get_nowait()
                if isinstance(item, tuple):
                    kind, value = item
                    if kind == 'error':
                        messagebox.showerror(self.t('error'), value)
                    else:
                        message = self.t('ended' if value in (0, -15) else 'crashed', code=value)
                        self.append(message)
                        if value not in (0, -15):
                            messagebox.showwarning(self.t('title'), message)
                    self.refresh_status()
                else:
                    self.append(item)
        except queue.Empty:
            pass
        self.root.after(100, self.pump)

    def quit(self):
        if self.process:
            self.process.terminate()
        self.root.destroy()


def main():
    # Packaged executable roles: --script <file> runs a preparation script, --play starts the
    # game with the saved settings and no launcher window (shortcuts, Steam).
    args = sys.argv[1:]
    if args[:1] == ['--script'] and len(args) > 1:
        sys.exit(tlg_run.run_script(args[1:]))
    if args[:1] == ['--clear-shader-cache']:
        sys.exit(tlg_run.main(args))
    if args[:1] == ['--play']:
        sys.exit(tlg_run.main(args[1:]))
    root = tk.Tk(className='tlg-pc')  # matches StartupWMClass in the desktop entry
    try:
        ttk.Style().theme_use('clam')
    except tk.TclError:
        pass
    Launcher(root)
    root.mainloop()


if __name__ == '__main__':
    main()
